def solve_sudoku(grid: str) -> str:
    if len(grid) != 81:
        raise ValueError("grid must be 81 characters")
    for ch in grid:
        if ch not in '123456789.':
            raise ValueError("invalid character in grid")

    cells = [int(ch) if ch != '.' else 0 for ch in grid]

    units = [[] for _ in range(81)]
    peers = [[] for _ in range(81)]
    for i in range(81):
        r, c = divmod(i, 9)
        row = [r * 9 + j for j in range(9)]
        col = [j * 9 + c for j in range(9)]
        box = [(r // 3 * 3 + dr) * 9 + (c // 3 * 3 + dc)
               for dr in range(3) for dc in range(3)]
        units[i] = [row, col, box]
        peer_set = set()
        for u in (row, col, box):
            peer_set.update(u)
        peer_set.discard(i)
        peers[i] = list(peer_set)

    for i in range(81):
        if cells[i] == 0:
            continue
        for j in peers[i]:
            if cells[j] == cells[i]:
                raise ValueError("conflict in initial grid")

    full_mask = 0x3FE
    candidates = [full_mask for _ in range(81)]
    for i in range(81):
        if cells[i] != 0:
            candidates[i] = 1 << cells[i]

    def assign(cells, candidates, i, val):
        mask = candidates[i]
        for v in range(1, 10):
            if v != val and (mask & (1 << v)):
                if not eliminate(cells, candidates, i, v):
                    return False
        return True

    def eliminate(cells, candidates, i, val):
        if not (candidates[i] & (1 << val)):
            return True
        candidates[i] &= ~(1 << val)
        if candidates[i] == 0:
            return False
        if candidates[i] & (candidates[i] - 1) == 0:
            remaining = candidates[i].bit_length() - 1
            for p in peers[i]:
                if not eliminate(cells, candidates, p, remaining):
                    return False
            cells[i] = remaining
        for unit in units[i]:
            places = 0
            only_place = -1
            for j in unit:
                if cells[j] == 0 and (candidates[j] & (1 << val)):
                    places += 1
                    only_place = j
            if places == 0:
                return False
            if places == 1:
                if not assign(cells, candidates, only_place, val):
                    return False
        return True

    solutions = [0]
    result = [None]

    cells_copy = cells[:]
    candidates_copy = candidates[:]
    ok = True
    for i in range(81):
        if cells_copy[i] != 0 and ok:
            ok = assign(cells_copy, candidates_copy, i, cells_copy[i])
    if not ok:
        raise ValueError("no solution")

    def solve(cells, candidates):
        if solutions[0] >= 2:
            return
        if all(c != 0 for c in cells):
            solutions[0] += 1
            if solutions[0] == 1:
                result[0] = ''.join(str(c) for c in cells)
            return
        best = -1
        best_count = 10
        for i in range(81):
            if cells[i] == 0:
                count = candidates[i].bit_count()
                if count < best_count:
                    best_count = count
                    best = i
                    if count == 1:
                        break
        if best == -1:
            return
        mask = candidates[best]
        for v in range(1, 10):
            if mask & (1 << v):
                c2 = cells[:]
                d2 = candidates[:]
                if assign(c2, d2, best, v):
                    solve(c2, d2)
                    if solutions[0] >= 2:
                        return

    solve(cells_copy, candidates_copy)

    if solutions[0] == 0:
        raise ValueError("no solution")
    if solutions[0] >= 2:
        raise ValueError("multiple solutions")
    return result[0]
